package com.company.platform.integration.framework;import java.util.*;import org.springframework.stereotype.Component;@Component public class AdapterRegistry{private final Map<String,InboundAdapter> inbound=new HashMap<>();private final Map<String,OutboundAdapter> outbound=new HashMap<>();public AdapterRegistry(List<InboundAdapter> ins,List<OutboundAdapter> outs){ins.forEach(x->inbound.put(x.provider(),x));outs.forEach(x->outbound.put(x.provider(),x));}public InboundAdapter inbound(String p){return Optional.ofNullable(inbound.get(p)).orElseThrow(()->new IllegalArgumentException("inbound adapter not found: "+p));}public OutboundAdapter outbound(String p){return Optional.ofNullable(outbound.get(p)).orElseThrow(()->new IllegalArgumentException("outbound adapter not found: "+p));}public Set<String> providers(){Set<String>x=new TreeSet<>(inbound.keySet());x.addAll(outbound.keySet());return x;}}
